if (controller.enableInputs && enabled) {
  if (movement) {
    action(controller, startPosition, movement);
    activateInertia(controller, inertiaStateName);
  } else if (inertiaConstant < 1.0) {
    maintainInertia(
      aggregator,
      type,
      modifier,
      inertiaConstant,
      action,
      controller,
      inertiaStateName,
    );
  }
} else if (defined(inertiaStateName)) {
  let movementState = controller[inertiaStateName];
  if (!defined(movementState)) {
    movementState = controller[inertiaStateName] = {
      startPosition: new Cartesian2(),
      endPosition: new Cartesian2(),
      motion: new Cartesian2(),
      inertiaEnabled: false,
    };
  } else {
    movementState.inertiaEnabled = false;
  }
}

